import os, sys, zipfile
_S = {"exportar": '# TTOKEN - EXPORTA O tiny-sd PARA O MOTOR CUBICO: pesos em .ttq (8 bits, cubo 8x8) + referencias do torch.\n# Gera: tinysd_unet_q8.ttq, tinysd_texto_q8.ttq, tinysd_vae_q8.ttq, tinysd_ref.npz, tinysd_config.json e baixa um .zip.\n# Depois eu portei o UNet no motor_cubico e comparo camada por camada com tinysd_ref.npz (sem precisar de torch).\n# NAO FOI EXECUTADO AINDA (o sandbox onde escrevi nao tem torch): rode e me mande o que imprimir + o .zip.\nimport os, sys, time, subprocess\nsubprocess.run([sys.executable, "-m", "pip", "install", "-q", "diffusers", "transformers", "accelerate"])\nimport numpy as np, torch, types\n# --- cubo_quant.py embutido (nao precisa subir mais nenhum arquivo) ---\n_CODIGO = r\'\'\'"""CUBO-QUANT: quantizacao de pesos em CUBOS (blocos) de 4 bits + leitor em streaming.\n\nSem torch: so numpy. Serve para o Colab (comprimir) e para o Pydroid 3 (ler).\n\nO que era errado no codigo antigo (erro \'cannot reshape array of size 12800 into shape\n(320,4,3,3)\'): para quantizar, a matriz era COMPLETADA com zeros ate ser multiplo de 8\n(36 colunas -> 40; 320*40 = 12800), mas na hora de ler ninguem cortava esse enchimento antes de\nvoltar a forma original (320*4*3*3 = 11520). Aqui a forma original e o tamanho real ficam\ngravados no arquivo e o enchimento e sempre cortado.\n\nOutra correcao honesta: o "Q4" antigo guardava cada valor de 4 bits num int8 (1 byte), entao so\nchegava a 1/4 do FP32. Aqui dois valores de 4 bits sao empacotados em 1 byte (1/8 do FP32).\n\nFormato .ttq:  b"TTQ1" | uint64 tamanho do cabecalho | cabecalho JSON | blobs (alinhados em 8).\nCada tensor 2D+ vira matriz (linhas x resto); a matriz e cortada em cubos bh x bw; cada cubo tem\nUMA escala (float16) = max|cubo| / 7; os valores vao de -8 a 7 (guardados como 0..15).\n"""\nimport json\nimport mmap\nimport os\nimport struct\nimport sys\n\nimport numpy as np\n\nMAGICO = b"TTQ1"\nMIN_ELEMENTOS = 256          # tensores menores (bias, norm) ficam em float16, sem perda\n\n\ndef _alinha(n, a=8):\n    return (n + a - 1) // a * a\n\n\ndef quantizar(arr, bloco=(8, 8), bits=4):\n    """Devolve (empacotado uint8, escalas float16, linhas, colunas) de um tensor >= 2D.\n    bits=4: 2 valores por byte (-8..7). bits=8: 1 valor por byte (-128..127), mais qualidade."""\n    bh, bw = bloco\n    arr = np.asarray(arr, dtype=np.float32)\n    m = arr.reshape(arr.shape[0], -1)\n    R, C = m.shape\n    Rp, Cp = _alinha(R, bh), _alinha(C, bw)\n    p = np.zeros((Rp, Cp), dtype=np.float32)\n    p[:R, :C] = m\n    b = p.reshape(Rp // bh, bh, Cp // bw, bw).transpose(0, 2, 1, 3)       # (nbh, nbw, bh, bw)\n    maximo = np.abs(b).max(axis=(2, 3))\n    nivel = 7.0 if bits == 4 else 127.0\n    esc = np.where(maximo == 0, 1.0, maximo / nivel).astype(np.float16)\n    esc32 = esc.astype(np.float32)                    # usa a escala JA arredondada (consistente)\n    q = np.rint(b / esc32[:, :, None, None])\n    if bits == 4:\n        plano = (np.clip(q, -8, 7).astype(np.int8) + 8).astype(np.uint8).reshape(-1)\n        if plano.size % 2:\n            plano = np.concatenate([plano, np.zeros(1, np.uint8)])\n        return ((plano[0::2] << 4) | plano[1::2]).astype(np.uint8), esc, R, C\n    return (np.clip(q, -128, 127).astype(np.int16) + 128).astype(np.uint8).reshape(-1), esc, R, C\n\n\ndef desquantizar(pack, esc, R, C, forma, bloco=(8, 8), dtype=np.float32, bits=4,\n                 max_elementos=1 << 16):\n    """Reconstroi POR PARTES (algumas linhas de cubos por vez): os temporarios ficam pequenos,\n    so o resultado final ocupa a RAM do tensor. Corta o enchimento e volta a forma original."""\n    bh, bw = bloco\n    nbh, nbw = _alinha(R, bh) // bh, _alinha(C, bw) // bw\n    esc = esc.astype(np.float32).reshape(nbh, nbw)\n    por_linha = nbw * bh * bw                           # elementos de uma linha de cubos\n    passo = max(1, max_elementos // por_linha)\n    if bits == 4 and por_linha % 2:                     # cubo impar: nao da para partir no meio do byte\n        passo = nbh\n    out = np.empty((R, C), dtype=np.float32)\n    for a in range(0, nbh, passo):\n        z = min(nbh, a + passo)\n        i0, i1 = a * por_linha, z * por_linha\n        if bits == 4:\n            bytes_ = pack[i0 // 2:(i1 + 1) // 2]\n            plano = np.empty(bytes_.size * 2, dtype=np.uint8)\n            plano[0::2] = bytes_ >> 4\n            plano[1::2] = bytes_ & 15\n            q = plano[:i1 - i0].astype(np.float32) - 8.0\n        else:\n            q = pack[i0:i1].astype(np.float32) - 128.0\n        blocos = q.reshape(z - a, nbw, bh, bw) * esc[a:z, :, None, None]\n        faixa = blocos.transpose(0, 2, 1, 3).reshape((z - a) * bh, nbw * bw)\n        r0, r1 = a * bh, min(R, z * bh)\n        out[r0:r1, :] = faixa[:r1 - r0, :C]\n    return out.reshape(forma).astype(dtype, copy=False)\n\n\ndef ordem_cubo(m):\n    """Permutacao de linhas e colunas que junta valores de tamanho parecido (como arrumar as\n    pecas do cubo magico por cor): ordena por energia. Cubos vizinhos ficam com faixa de valores\n    parecida, a escala de cada cubo fica justa e o MESMO numero de bits erra menos."""\n    pr = np.argsort(np.abs(m).max(axis=1))\n    pc = np.argsort(np.abs(m).max(axis=0))\n    return pr, pc\n\n\ndef erro(original, recuperado):\n    """Metricas honestas: SNR em dB, erro maximo e erro medio relativo."""\n    o = np.asarray(original, np.float64).ravel()\n    r = np.asarray(recuperado, np.float64).ravel()\n    ruido = np.sum((o - r) ** 2)\n    sinal = np.sum(o ** 2)\n    snr = float("inf") if ruido == 0 else 10 * np.log10(max(sinal, 1e-30) / ruido)\n    return {"snr_db": round(float(snr), 2), "erro_max": float(np.abs(o - r).max()),\n            "erro_medio_rel": float(np.abs(o - r).mean() / (np.abs(o).mean() + 1e-12))}\n\n\n# ------------------------------------------------------------------ gravar\ndef salvar(estado, caminho, bloco=(8, 8), bits=4, reordenar=False):\n    """estado: dict nome -> ndarray. Grava o .ttq (atomico). Devolve estatisticas."""\n    meta, blobs, pos = {}, [], 0\n    bruto = 0\n    for nome, arr in estado.items():\n        arr = np.asarray(arr)\n        bruto += arr.size * 4\n        if arr.ndim >= 2 and arr.size >= MIN_ELEMENTOS:\n            m = arr.astype(np.float32).reshape(arr.shape[0], -1)\n            pr = pc = None\n            if reordenar:                                  # "resolve o cubo": agrupa parecidos\n                pr, pc = ordem_cubo(m)\n                m = m[pr][:, pc]\n            pack, esc, R, C = quantizar(m, bloco, bits)\n            dados = [pack.tobytes(), esc.tobytes()]\n            meta[nome] = {"modo": "q%d" % bits, "forma": list(arr.shape), "R": R, "C": C,\n                          "off": pos, "n": len(dados[0]),\n                          "off_esc": pos + _alinha(len(dados[0])), "n_esc": len(dados[1])}\n            tamanho = _alinha(len(dados[0])) + _alinha(len(dados[1]))\n            blobs.append((pos, dados[0])); blobs.append((meta[nome]["off_esc"], dados[1]))\n            if pr is not None:\n                dr, dc = pr.astype(np.uint32).tobytes(), pc.astype(np.uint32).tobytes()\n                meta[nome]["off_pr"], meta[nome]["off_pc"] = pos + tamanho, pos + tamanho + _alinha(len(dr))\n                blobs.append((meta[nome]["off_pr"], dr)); blobs.append((meta[nome]["off_pc"], dc))\n                tamanho += _alinha(len(dr)) + _alinha(len(dc))\n        else:\n            d = np.ascontiguousarray(arr.astype(np.float16)).tobytes()\n            meta[nome] = {"modo": "f16", "forma": list(arr.shape), "off": pos, "n": len(d)}\n            blobs.append((pos, d))\n            tamanho = _alinha(len(d))\n        pos += tamanho\n    cab = json.dumps({"bloco": list(bloco), "bits": bits, "tensores": meta}).encode("utf-8")\n    ini = _alinha(4 + 8 + len(cab))\n    tmp = caminho + ".tmp"\n    with open(tmp, "wb") as f:\n        f.write(MAGICO + struct.pack("<Q", len(cab)) + cab)\n        f.write(b"\\0" * (ini - 12 - len(cab)))\n        for off, d in blobs:\n            f.seek(ini + off)\n            f.write(d)\n        f.truncate(ini + pos)\n    os.replace(tmp, caminho)\n    final = os.path.getsize(caminho)\n    return {"bruto_fp32_mb": bruto / 2**20, "arquivo_mb": final / 2**20,\n            "economia_pct": round(100 * (1 - final / max(bruto, 1)), 1)}\n\n\n# ------------------------------------------------------------------ ler (streaming)\nclass Leitor:\n    """Le UM tensor por vez direto do arquivo (mmap): a RAM so guarda o tensor em uso."""\n\n    def __init__(self, caminho):\n        self._f = open(caminho, "rb")\n        if self._f.read(4) != MAGICO:\n            self._f.close()\n            raise ValueError("arquivo nao e um .ttq valido")\n        (n,) = struct.unpack("<Q", self._f.read(8))\n        cab = json.loads(self._f.read(n).decode("utf-8"))\n        self.bloco = tuple(cab["bloco"])\n        self.bits = int(cab.get("bits", 4))\n        self.meta = cab["tensores"]\n        self._ini = _alinha(12 + n)\n        self._mm = mmap.mmap(self._f.fileno(), 0, access=mmap.ACCESS_READ)\n\n    def nomes(self):\n        return list(self.meta)\n\n    def ler(self, nome, dtype=np.float32):\n        t = self.meta[nome]\n        forma = tuple(t["forma"])\n        base = self._ini\n        if t["modo"] == "f16":\n            d = np.frombuffer(self._mm, np.float16, count=int(np.prod(forma, dtype=np.int64)),\n                              offset=base + t["off"])\n            return d.reshape(forma).astype(dtype)\n        pack = np.frombuffer(self._mm, np.uint8, count=t["n"], offset=base + t["off"])\n        esc = np.frombuffer(self._mm, np.float16, count=t["n_esc"] // 2,\n                            offset=base + t["off_esc"])\n        bh, bw = self.bloco\n        esc = esc.reshape(_alinha(t["R"], bh) // bh, _alinha(t["C"], bw) // bw)\n        if "off_pr" in t:                                    # desfaz a reordenacao do cubo\n            m = desquantizar(pack, esc, t["R"], t["C"], (t["R"], t["C"]), self.bloco, np.float32, self.bits)\n            pr = np.frombuffer(self._mm, np.uint32, count=t["R"], offset=base + t["off_pr"])\n            pc = np.frombuffer(self._mm, np.uint32, count=t["C"], offset=base + t["off_pc"])\n            ir, ic = np.argsort(pr), np.argsort(pc)\n            return m[ir][:, ic].reshape(forma).astype(dtype, copy=False)\n        return desquantizar(pack, esc, t["R"], t["C"], forma, self.bloco, dtype, self.bits)\n\n    def itens(self):\n        for nome in self.meta:\n            yield nome, self.ler(nome)\n\n    def fechar(self):\n        try:\n            self._mm.close()\n        finally:\n            self._f.close()\n\n    def __enter__(self):\n        return self\n\n    def __exit__(self, *a):\n        self.fechar()\n\n\ndef para_torch(caminho, dispositivo="cpu", dtype_nome="float16"):\n    """Colab: monta um state_dict do PyTorch lendo o .ttq (importa torch so aqui)."""\n    import torch\n    dt = getattr(torch, dtype_nome)\n    sd = {}\n    with Leitor(caminho) as lt:\n        for nome, arr in lt.itens():\n            sd[nome] = torch.from_numpy(arr).to(dispositivo).to(dt)\n    return sd\n\n\ndef de_safetensors(entrada, saida, bloco=(8, 8), bits=4):\n    """Converte um .safetensors (so float32/float16) em .ttq. Precisa de `safetensors`."""\n    from safetensors.numpy import load_file\n    return salvar(load_file(entrada), saida, bloco, bits)\n\n\n\'\'\'\ncq = types.ModuleType("cubo_quant"); exec(_CODIGO, cq.__dict__); sys.modules["cubo_quant"] = cq\n\nimport json, zipfile\nfrom diffusers import AutoPipelineForText2Image\nSEED, PROMPT = 5762, "Carro futurista correndo na chuva cyberpunk"\nBLOCO, BITS = (4, 4), 8      # 4x4 deu SSIM 0.963 (pior 0.940); 8x8 so 0.900 (pior 0.843)\npipe = AutoPipelineForText2Image.from_pretrained("segmind/tiny-sd", torch_dtype=torch.float32)\npipe.set_progress_bar_config(disable=True)\nif hasattr(pipe, "safety_checker"): pipe.safety_checker = None\nunet, te, vae, tok = pipe.unet.eval(), pipe.text_encoder.eval(), pipe.vae.eval(), pipe.tokenizer\n\ndef estado_np(m):\n    return {k: v.detach().float().numpy() for k, v in m.state_dict().items() if v.is_floating_point()}\n\n# 1) pesos -> .ttq\narquivos = []\nfor nome, m in (("unet", unet), ("texto", te), ("vae", vae)):\n    cam = "tinysd_%s_q8.ttq" % nome\n    est = cq.salvar(estado_np(m), cam, BLOCO, BITS)\n    arquivos.append(cam)\n    print(nome, "->", cam, "%.1f MB" % (os.path.getsize(cam) / 1e6), est)\njson.dump({"unet": dict(unet.config), "vae": dict(vae.config), "texto": te.config.to_dict()},\n          open("tinysd_config.json", "w"), default=str, indent=1)\narquivos.append("tinysd_config.json")\n\n# 2) referencias do torch (fp32) e do UNet com pesos de 8 bits\ndef ids(texto):\n    return tok(texto, padding="max_length", max_length=tok.model_max_length, truncation=True, return_tensors="pt").input_ids\nref = {}\nwith torch.no_grad():\n    for rot, txt in (("cond", PROMPT), ("incond", "")):\n        ref["ids_" + rot] = ids(txt).numpy()\n        ref["texto_" + rot] = te(ids(txt))[0].numpy()\n    g = torch.Generator("cpu").manual_seed(SEED)\n    lat = torch.randn(1, unet.config.in_channels, 32, 32, generator=g)\n    ref["latente"] = lat.numpy()\n    saidas = {}\n    def gancho(nome):\n        def f(mod, inp, out):\n            saidas[nome] = (out[0] if isinstance(out, tuple) else out).detach().float().numpy()\n        return f\n    hs = [unet.conv_in.register_forward_hook(gancho("conv_in")),\n          unet.time_embedding.register_forward_hook(gancho("time_embedding")),\n          unet.conv_out.register_forward_hook(gancho("conv_out"))]\n    if unet.mid_block is not None:          # o tiny-sd NAO tem bloco do meio (e None)\n        hs.append(unet.mid_block.register_forward_hook(gancho("mid_block")))\n    hs += [b.register_forward_hook(gancho("down_%d" % i)) for i, b in enumerate(unet.down_blocks)]\n    hs += [b.register_forward_hook(gancho("up_%d" % i)) for i, b in enumerate(unet.up_blocks)]\n    def rodar(tag):\n        for t in (999, 500, 100):\n            saidas.clear()\n            y = unet(lat, torch.tensor([t]), encoder_hidden_states=torch.from_numpy(ref["texto_cond"])).sample\n            ref["%s_t%d_saida" % (tag, t)] = y.numpy()\n            for k, v in saidas.items(): ref["%s_t%d_%s" % (tag, t, k)] = v\n    rodar("fp32")\n    # trocar pelos pesos lidos do .ttq (8 bits) e repetir\n    with cq.Leitor("tinysd_unet_q8.ttq") as lt:\n        sd = {k: torch.from_numpy(np.asarray(v, np.float32)) for k, v in lt.itens()}\n    original = {k: v.clone() for k, v in unet.state_dict().items()}\n    unet.load_state_dict(sd, strict=False)\n    rodar("q8")\n    for h in hs: h.remove()\n    unet.load_state_dict(original)\n    # VAE: decodifica o latente de referencia\n    ref["vae_entrada"] = (lat / vae.config.scaling_factor).numpy()\n    ref["vae_saida"] = vae.decode(torch.from_numpy(ref["vae_entrada"])).sample.numpy()\nnp.savez_compressed("tinysd_ref.npz", **ref); arquivos.append("tinysd_ref.npz")\n\nprint("\\nSNR do UNet com pesos 8 bits vs fp32 (por passo de tempo):")\nfor t in (999, 500, 100):\n    a, b = ref["fp32_t%d_saida" % t], ref["q8_t%d_saida" % t]\n    snr = 10 * np.log10((a ** 2).mean() / (((a - b) ** 2).mean() + 1e-30))\n    print("   t=%d: %.1f dB" % (t, snr))\n\n# 3) imagem completa de referencia (4 passos, mesmos dados)\nimg = pipe(prompt=PROMPT, num_inference_steps=4, guidance_scale=7.5,\n           generator=torch.Generator("cpu").manual_seed(SEED), height=256, width=256).images[0]\nimg.save("tinysd_ref.png"); arquivos.append("tinysd_ref.png")\n\nwith zipfile.ZipFile("tinysd_cubo.zip", "w", zipfile.ZIP_STORED) as z:\n    for a in arquivos: z.write(a)\nprint("\\nPRONTO: tinysd_cubo.zip = %.1f MB (%d arquivos)" % (os.path.getsize("tinysd_cubo.zip") / 1e6, len(arquivos)))\ntry:\n    from google.colab import files; files.download("tinysd_cubo.zip")\nexcept Exception:\n    print("Baixe tinysd_cubo.zip pelo painel de arquivos do Colab.")\n', "validar UNet": '# TTOKEN - VALIDA O UNet EM NUMPY (motor cubico) CONTRA O TORCH. Rode no MESMO Colab das exportacoes.\n# Usa tinysd_ref.npz e, se existirem, tinysd_unet_q8.ttq (4x4 uniforme) e tinysd_unet_final.ttq / tinysd_unet_curva.ttq (receita mista).\n# Para o q8: compara numpy x torch com os MESMOS pesos (tem de dar > 60 dB: prova que o motor esta CERTO).\n# Para os mistos: mostra a fidelidade contra o fp32 original. Arquivo UNICO.\nimport sys, types, time, os, resource\nimport numpy as np\n_C = \'"""CUBO-QUANT: quantizacao de pesos em CUBOS (blocos) de 4 bits + leitor em streaming.\\n\\nSem torch: so numpy. Serve para o Colab (comprimir) e para o Pydroid 3 (ler).\\n\\nO que era errado no codigo antigo (erro \\\'cannot reshape array of size 12800 into shape\\n(320,4,3,3)\\\'): para quantizar, a matriz era COMPLETADA com zeros ate ser multiplo de 8\\n(36 colunas -> 40; 320*40 = 12800), mas na hora de ler ninguem cortava esse enchimento antes de\\nvoltar a forma original (320*4*3*3 = 11520). Aqui a forma original e o tamanho real ficam\\ngravados no arquivo e o enchimento e sempre cortado.\\n\\nOutra correcao honesta: o "Q4" antigo guardava cada valor de 4 bits num int8 (1 byte), entao so\\nchegava a 1/4 do FP32. Aqui dois valores de 4 bits sao empacotados em 1 byte (1/8 do FP32).\\n\\nFormato .ttq:  b"TTQ1" | uint64 tamanho do cabecalho | cabecalho JSON | blobs (alinhados em 8).\\nCada tensor 2D+ vira matriz (linhas x resto); a matriz e cortada em cubos bh x bw; cada cubo tem\\nUMA escala (float16) = max|cubo| / 7; os valores vao de -8 a 7 (guardados como 0..15).\\n"""\\nimport json\\nimport mmap\\nimport os\\nimport struct\\nimport sys\\n\\nimport numpy as np\\n\\nMAGICO = b"TTQ1"\\nMIN_ELEMENTOS = 256          # tensores menores (bias, norm) ficam em float16, sem perda\\n\\n\\ndef _alinha(n, a=8):\\n    return (n + a - 1) // a * a\\n\\n\\ndef quantizar(arr, bloco=(8, 8), bits=4):\\n    """Devolve (empacotado uint8, escalas float16, linhas, colunas) de um tensor >= 2D.\\n    bits=4: 2 valores por byte (-8..7). bits=8: 1 valor por byte (-128..127), mais qualidade."""\\n    bh, bw = bloco\\n    arr = np.asarray(arr, dtype=np.float32)\\n    m = arr.reshape(arr.shape[0], -1)\\n    R, C = m.shape\\n    Rp, Cp = _alinha(R, bh), _alinha(C, bw)\\n    p = np.zeros((Rp, Cp), dtype=np.float32)\\n    p[:R, :C] = m\\n    b = p.reshape(Rp // bh, bh, Cp // bw, bw).transpose(0, 2, 1, 3)       # (nbh, nbw, bh, bw)\\n    maximo = np.abs(b).max(axis=(2, 3))\\n    nivel = 7.0 if bits == 4 else 127.0\\n    esc = np.where(maximo == 0, 1.0, maximo / nivel).astype(np.float16)\\n    esc32 = esc.astype(np.float32)                    # usa a escala JA arredondada (consistente)\\n    q = np.rint(b / esc32[:, :, None, None])\\n    if bits == 4:\\n        plano = (np.clip(q, -8, 7).astype(np.int8) + 8).astype(np.uint8).reshape(-1)\\n        if plano.size % 2:\\n            plano = np.concatenate([plano, np.zeros(1, np.uint8)])\\n        return ((plano[0::2] << 4) | plano[1::2]).astype(np.uint8), esc, R, C\\n    return (np.clip(q, -128, 127).astype(np.int16) + 128).astype(np.uint8).reshape(-1), esc, R, C\\n\\n\\ndef desquantizar(pack, esc, R, C, forma, bloco=(8, 8), dtype=np.float32, bits=4,\\n                 max_elementos=1 << 16):\\n    """Reconstroi POR PARTES (algumas linhas de cubos por vez): os temporarios ficam pequenos,\\n    so o resultado final ocupa a RAM do tensor. Corta o enchimento e volta a forma original."""\\n    bh, bw = bloco\\n    nbh, nbw = _alinha(R, bh) // bh, _alinha(C, bw) // bw\\n    esc = esc.astype(np.float32).reshape(nbh, nbw)\\n    por_linha = nbw * bh * bw                           # elementos de uma linha de cubos\\n    passo = max(1, max_elementos // por_linha)\\n    if bits == 4 and por_linha % 2:                     # cubo impar: nao da para partir no meio do byte\\n        passo = nbh\\n    out = np.empty((R, C), dtype=np.float32)\\n    for a in range(0, nbh, passo):\\n        z = min(nbh, a + passo)\\n        i0, i1 = a * por_linha, z * por_linha\\n        if bits == 4:\\n            bytes_ = pack[i0 // 2:(i1 + 1) // 2]\\n            plano = np.empty(bytes_.size * 2, dtype=np.uint8)\\n            plano[0::2] = bytes_ >> 4\\n            plano[1::2] = bytes_ & 15\\n            q = plano[:i1 - i0].astype(np.float32) - 8.0\\n        else:\\n            q = pack[i0:i1].astype(np.float32) - 128.0\\n        blocos = q.reshape(z - a, nbw, bh, bw) * esc[a:z, :, None, None]\\n        faixa = blocos.transpose(0, 2, 1, 3).reshape((z - a) * bh, nbw * bw)\\n        r0, r1 = a * bh, min(R, z * bh)\\n        out[r0:r1, :] = faixa[:r1 - r0, :C]\\n    return out.reshape(forma).astype(dtype, copy=False)\\n\\n\\ndef ordem_cubo(m):\\n    """Permutacao de linhas e colunas que junta valores de tamanho parecido (como arrumar as\\n    pecas do cubo magico por cor): ordena por energia. Cubos vizinhos ficam com faixa de valores\\n    parecida, a escala de cada cubo fica justa e o MESMO numero de bits erra menos."""\\n    pr = np.argsort(np.abs(m).max(axis=1))\\n    pc = np.argsort(np.abs(m).max(axis=0))\\n    return pr, pc\\n\\n\\ndef erro(original, recuperado):\\n    """Metricas honestas: SNR em dB, erro maximo e erro medio relativo."""\\n    o = np.asarray(original, np.float64).ravel()\\n    r = np.asarray(recuperado, np.float64).ravel()\\n    ruido = np.sum((o - r) ** 2)\\n    sinal = np.sum(o ** 2)\\n    snr = float("inf") if ruido == 0 else 10 * np.log10(max(sinal, 1e-30) / ruido)\\n    return {"snr_db": round(float(snr), 2), "erro_max": float(np.abs(o - r).max()),\\n            "erro_medio_rel": float(np.abs(o - r).mean() / (np.abs(o).mean() + 1e-12))}\\n\\n\\n# ------------------------------------------------------------------ gravar\\ndef salvar(estado, caminho, bloco=(8, 8), bits=4, reordenar=False, receita=None):\\n    """estado: dict nome -> ndarray. Grava o .ttq (atomico). Devolve estatisticas.\\n    receita (opcional): dict nome -> "fp16" | ((bh, bw), bits). Permite um cubo/precisao DIFERENTE por tensor\\n    (ex.: camadas sensiveis em fp16 ou 2x2, o resto em 4x4). Quem nao aparece usa (bloco, bits)."""\\n    receita = receita or {}\\n    meta, blobs, pos = {}, [], 0\\n    bruto = 0\\n    for nome, arr in estado.items():\\n        arr = np.asarray(arr)\\n        bruto += arr.size * 4\\n        rec = receita.get(nome)\\n        if rec == "fp16":\\n            rec_bloco, rec_bits = None, None\\n        else:\\n            rec_bloco, rec_bits = (tuple(rec[0]), int(rec[1])) if rec else (tuple(bloco), bits)\\n        if arr.ndim >= 2 and arr.size >= MIN_ELEMENTOS and rec != "fp16":\\n            m = arr.astype(np.float32).reshape(arr.shape[0], -1)\\n            pr = pc = None\\n            if reordenar:                                  # "resolve o cubo": agrupa parecidos\\n                pr, pc = ordem_cubo(m)\\n                m = m[pr][:, pc]\\n            pack, esc, R, C = quantizar(m, rec_bloco, rec_bits)\\n            dados = [pack.tobytes(), esc.tobytes()]\\n            meta[nome] = {"modo": "q%d" % rec_bits, "forma": list(arr.shape), "R": R, "C": C,\\n                          "off": pos, "n": len(dados[0]),\\n                          "off_esc": pos + _alinha(len(dados[0])), "n_esc": len(dados[1])}\\n            if rec:                                          # so grava por tensor quando a receita pediu\\n                meta[nome]["bloco"], meta[nome]["bits"] = list(rec_bloco), rec_bits\\n            tamanho = _alinha(len(dados[0])) + _alinha(len(dados[1]))\\n            blobs.append((pos, dados[0])); blobs.append((meta[nome]["off_esc"], dados[1]))\\n            if pr is not None:\\n                dr, dc = pr.astype(np.uint32).tobytes(), pc.astype(np.uint32).tobytes()\\n                meta[nome]["off_pr"], meta[nome]["off_pc"] = pos + tamanho, pos + tamanho + _alinha(len(dr))\\n                blobs.append((meta[nome]["off_pr"], dr)); blobs.append((meta[nome]["off_pc"], dc))\\n                tamanho += _alinha(len(dr)) + _alinha(len(dc))\\n        else:\\n            d = np.ascontiguousarray(arr.astype(np.float16)).tobytes()\\n            meta[nome] = {"modo": "f16", "forma": list(arr.shape), "off": pos, "n": len(d)}\\n            blobs.append((pos, d))\\n            tamanho = _alinha(len(d))\\n        pos += tamanho\\n    cab = json.dumps({"bloco": list(bloco), "bits": bits, "tensores": meta}).encode("utf-8")\\n    ini = _alinha(4 + 8 + len(cab))\\n    tmp = caminho + ".tmp"\\n    with open(tmp, "wb") as f:\\n        f.write(MAGICO + struct.pack("<Q", len(cab)) + cab)\\n        f.write(b"\\\\0" * (ini - 12 - len(cab)))\\n        for off, d in blobs:\\n            f.seek(ini + off)\\n            f.write(d)\\n        f.truncate(ini + pos)\\n    os.replace(tmp, caminho)\\n    final = os.path.getsize(caminho)\\n    return {"bruto_fp32_mb": bruto / 2**20, "arquivo_mb": final / 2**20,\\n            "economia_pct": round(100 * (1 - final / max(bruto, 1)), 1)}\\n\\n\\n# ------------------------------------------------------------------ ler (streaming)\\nclass Leitor:\\n    """Le UM tensor por vez direto do arquivo (mmap): a RAM so guarda o tensor em uso."""\\n\\n    def __init__(self, caminho):\\n        self._f = open(caminho, "rb")\\n        if self._f.read(4) != MAGICO:\\n            self._f.close()\\n            raise ValueError("arquivo nao e um .ttq valido")\\n        (n,) = struct.unpack("<Q", self._f.read(8))\\n        cab = json.loads(self._f.read(n).decode("utf-8"))\\n        self.bloco = tuple(cab["bloco"])\\n        self.bits = int(cab.get("bits", 4))\\n        self.meta = cab["tensores"]\\n        self._ini = _alinha(12 + n)\\n        self._mm = mmap.mmap(self._f.fileno(), 0, access=mmap.ACCESS_READ)\\n\\n    def nomes(self):\\n        return list(self.meta)\\n\\n    def ler(self, nome, dtype=np.float32):\\n        t = self.meta[nome]\\n        forma = tuple(t["forma"])\\n        base = self._ini\\n        if t["modo"] == "f16":\\n            d = np.frombuffer(self._mm, np.float16, count=int(np.prod(forma, dtype=np.int64)),\\n                              offset=base + t["off"])\\n            return d.reshape(forma).astype(dtype)\\n        pack = np.frombuffer(self._mm, np.uint8, count=t["n"], offset=base + t["off"])\\n        esc = np.frombuffer(self._mm, np.float16, count=t["n_esc"] // 2,\\n                            offset=base + t["off_esc"])\\n        bloco_t = tuple(t.get("bloco", self.bloco))\\n        bits_t = int(t.get("bits", self.bits))\\n        bh, bw = bloco_t\\n        esc = esc.reshape(_alinha(t["R"], bh) // bh, _alinha(t["C"], bw) // bw)\\n        if "off_pr" in t:                                    # desfaz a reordenacao do cubo\\n            m = desquantizar(pack, esc, t["R"], t["C"], (t["R"], t["C"]), bloco_t, np.float32, bits_t)\\n            pr = np.frombuffer(self._mm, np.uint32, count=t["R"], offset=base + t["off_pr"])\\n            pc = np.frombuffer(self._mm, np.uint32, count=t["C"], offset=base + t["off_pc"])\\n            ir, ic = np.argsort(pr), np.argsort(pc)\\n            return m[ir][:, ic].reshape(forma).astype(dtype, copy=False)\\n        return desquantizar(pack, esc, t["R"], t["C"], forma, bloco_t, dtype, bits_t)\\n\\n    def itens(self):\\n        for nome in self.meta:\\n            yield nome, self.ler(nome)\\n\\n    def fechar(self):\\n        try:\\n            self._mm.close()\\n        finally:\\n            self._f.close()\\n\\n    def __enter__(self):\\n        return self\\n\\n    def __exit__(self, *a):\\n        self.fechar()\\n\\n\\ndef para_torch(caminho, dispositivo="cpu", dtype_nome="float16"):\\n    """Colab: monta um state_dict do PyTorch lendo o .ttq (importa torch so aqui)."""\\n    import torch\\n    dt = getattr(torch, dtype_nome)\\n    sd = {}\\n    with Leitor(caminho) as lt:\\n        for nome, arr in lt.itens():\\n            sd[nome] = torch.from_numpy(arr).to(dispositivo).to(dt)\\n    return sd\\n\\n\\ndef de_safetensors(entrada, saida, bloco=(8, 8), bits=4):\\n    """Converte um .safetensors (so float32/float16) em .ttq. Precisa de `safetensors`."""\\n    from safetensors.numpy import load_file\\n    return salvar(load_file(entrada), saida, bloco, bits)\\n\\n\\nif __name__ == "__main__":      # python cubo_quant.py modelo.safetensors saida.ttq\\n    if len(sys.argv) != 3:\\n        print("uso: python cubo_quant.py entrada.safetensors saida.ttq")\\n        sys.exit(1)\\n    print(de_safetensors(sys.argv[1], sys.argv[2]))\\n\'\n_M = \'"""MOTOR CUBICO: roda camadas de uma rede de difusao em numpy (Python puro, sem torch),\\nlendo os pesos de um arquivo .ttq (cubos de 4 bits) UMA CAMADA POR VEZ.\\n\\nIdeia (do Fabio): o modelo e maior que a RAM do celular, entao\\n  1) os pesos ficam comprimidos em cubos de 4 bits no armazenamento (cubo_quant.py);\\n  2) a cada camada o motor "abre" so aquele pedaco, calcula e joga fora;\\n  3) as contas grandes (convolucao, atencao) tambem andam por partes (linhas / blocos).\\nO pico de RAM fica perto de  (ativacoes + a MAIOR camada)  e nao do tamanho do modelo.\\n\\nNomes dos pesos seguem o diffusers (resnets.0.norm1, attn1.to_q, ff.net.0.proj ...), entao\\nportar o UNet real do SDXS/SD e compor estes blocos. Os blocos sao validados contra\\nimplementacoes ingenuas nos testes; o UNet COMPLETO real ainda NAO foi validado (precisa dos\\npesos reais e de uma referencia).\\n"""\\nimport time\\nfrom collections import OrderedDict\\n\\nimport numpy as np\\nfrom numpy.lib.stride_tricks import sliding_window_view\\n\\ntry:\\n    import cubo_quant as cq\\nexcept ImportError:                                  # quando importado como pacote\\n    from . import cubo_quant as cq\\n\\n\\n# ------------------------------------------------------------------ pesos por partes\\nclass Pesos:\\n    """Entrega pesos float32 de um .ttq. cache_mb=0: nada fica na RAM depois do uso."""\\n\\n    def __init__(self, caminho, cache_mb=0):\\n        self.lt = cq.Leitor(caminho)\\n        self.cache_mb, self._cache, self._bytes = cache_mb, OrderedDict(), 0\\n        self.leituras = 0\\n        self.t_leitura = 0.0\\n\\n    def tem(self, nome):\\n        return nome in self.lt.meta\\n\\n    def __call__(self, nome):\\n        if nome in self._cache:\\n            self._cache.move_to_end(nome)\\n            return self._cache[nome]\\n        t = time.time()\\n        a = self.lt.ler(nome)\\n        self.t_leitura += time.time() - t\\n        self.leituras += 1\\n        if self.cache_mb and a.nbytes <= self.cache_mb * 2**20:\\n            self._cache[nome] = a\\n            self._bytes += a.nbytes\\n            while self._bytes > self.cache_mb * 2**20:\\n                _, v = self._cache.popitem(last=False)\\n                self._bytes -= v.nbytes\\n        return a\\n\\n    def fechar(self):\\n        self.lt.fechar()\\n\\n\\nclass PesosMemoria:\\n    """Mesma interface, pesos ja em RAM (referencia para comparar)."""\\n\\n    def __init__(self, estado):\\n        self.e = {k: np.asarray(v, np.float32) for k, v in estado.items()}\\n\\n    def tem(self, nome):\\n        return nome in self.e\\n\\n    def __call__(self, nome):\\n        return self.e[nome]\\n\\n\\n# ------------------------------------------------------------------ operacoes\\ndef silu(x):\\n    return x / (1.0 + np.exp(-x))\\n\\n\\ndef gelu(x):                                         # aproximacao tanh (erro ~1e-3)\\n    return 0.5 * x * (1.0 + np.tanh(0.7978845608 * (x + 0.044715 * x ** 3)))\\n\\n\\ndef linear(x, w, b=None):\\n    y = x @ w.T\\n    return y + b if b is not None else y\\n\\n\\ndef conv2d(x, w, b=None, stride=1, pad=0, linhas=16):\\n    """x (C,H,W), w (O,C,kh,kw). Anda `linhas` linhas de saida por vez (pouca RAM)."""\\n    C, H, W = x.shape\\n    O, _, kh, kw = w.shape\\n    xp = np.pad(x, ((0, 0), (pad, pad), (pad, pad))) if pad else x\\n    Ho, Wo = (H + 2 * pad - kh) // stride + 1, (W + 2 * pad - kw) // stride + 1\\n    out = np.empty((O, Ho, Wo), np.float32)\\n    wm = w.reshape(O, -1)\\n    jan = sliding_window_view(xp, (kh, kw), axis=(1, 2))[:, ::stride, ::stride]\\n    for r0 in range(0, Ho, linhas):\\n        r1 = min(Ho, r0 + linhas)\\n        cols = jan[:, r0:r1].transpose(1, 2, 0, 3, 4).reshape((r1 - r0) * Wo, C * kh * kw)\\n        out[:, r0:r1, :] = (cols @ wm.T).reshape(r1 - r0, Wo, O).transpose(2, 0, 1)\\n    if b is not None:\\n        out += b[:, None, None]\\n    return out\\n\\n\\ndef group_norm(x, g, b, grupos=32, eps=1e-5):\\n    C, H, W = x.shape\\n    xg = x.reshape(grupos, -1)\\n    m = xg.mean(axis=1, keepdims=True)\\n    v = xg.var(axis=1, keepdims=True)\\n    y = ((xg - m) / np.sqrt(v + eps)).reshape(C, H, W)\\n    return y * g[:, None, None] + b[:, None, None]\\n\\n\\ndef layer_norm(x, g, b, eps=1e-5):\\n    m = x.mean(-1, keepdims=True)\\n    v = x.var(-1, keepdims=True)\\n    return (x - m) / np.sqrt(v + eps) * g + b\\n\\n\\ndef atencao(q, k, v, cabecas, bloco=256):\\n    """q (N,D), k/v (M,D). Softmax por blocos de consultas (nao monta a matriz NxM inteira)."""\\n    N, D = q.shape\\n    d = D // cabecas\\n    qh = q.reshape(N, cabecas, d).transpose(1, 0, 2)\\n    kh = k.reshape(-1, cabecas, d).transpose(1, 2, 0)\\n    vh = v.reshape(-1, cabecas, d).transpose(1, 0, 2)\\n    out = np.empty((cabecas, N, d), np.float32)\\n    esc = 1.0 / np.sqrt(d)\\n    for i in range(0, N, bloco):\\n        s = (qh[:, i:i + bloco] @ kh) * esc\\n        s -= s.max(-1, keepdims=True)\\n        p = np.exp(s)\\n        p /= p.sum(-1, keepdims=True)\\n        out[:, i:i + bloco] = p @ vh\\n    return out.transpose(1, 0, 2).reshape(N, D)\\n\\n\\ndef sobe2x(x):\\n    return x.repeat(2, axis=1).repeat(2, axis=2)\\n\\n\\ndef _b(P, nome):\\n    return P(nome) if P.tem(nome) else None\\n\\n\\n# ------------------------------------------------------------------ blocos (nomes do diffusers)\\ndef bloco_resnet(x, temb, P, p, grupos=32):\\n    h = silu(group_norm(x, P(p + ".norm1.weight"), P(p + ".norm1.bias"), grupos))\\n    h = conv2d(h, P(p + ".conv1.weight"), P(p + ".conv1.bias"), pad=1)\\n    if temb is not None and P.tem(p + ".time_emb_proj.weight"):\\n        t = linear(silu(temb), P(p + ".time_emb_proj.weight"), P(p + ".time_emb_proj.bias"))\\n        h = h + t[:, None, None]\\n    h = silu(group_norm(h, P(p + ".norm2.weight"), P(p + ".norm2.bias"), grupos))\\n    h = conv2d(h, P(p + ".conv2.weight"), P(p + ".conv2.bias"), pad=1)\\n    if P.tem(p + ".conv_shortcut.weight"):\\n        x = conv2d(x, P(p + ".conv_shortcut.weight"), P(p + ".conv_shortcut.bias"))\\n    return x + h\\n\\n\\ndef _proj(h, P, nome):                               # conv 1x1 ou linear, conforme o peso\\n    w = P(nome + ".weight")\\n    b = _b(P, nome + ".bias")\\n    return linear(h, w.reshape(w.shape[0], -1), b)\\n\\n\\ndef _atn(h, ctx, P, p, cabecas):\\n    ctx = h if ctx is None else ctx\\n    q = linear(h, P(p + ".to_q.weight"))\\n    k = linear(ctx, P(p + ".to_k.weight"))\\n    v = linear(ctx, P(p + ".to_v.weight"))\\n    o = atencao(q, k, v, cabecas)\\n    return linear(o, P(p + ".to_out.0.weight"), P(p + ".to_out.0.bias"))\\n\\n\\ndef bloco_transformer(x, ctx, P, p, cabecas=8, grupos=32):\\n    C, H, W = x.shape\\n    h = group_norm(x, P(p + ".norm.weight"), P(p + ".norm.bias"), grupos, eps=1e-6)\\n    h = h.reshape(C, H * W).T\\n    h = _proj(h, P, p + ".proj_in")\\n    t = p + ".transformer_blocks.0"\\n    h = h + _atn(layer_norm(h, P(t + ".norm1.weight"), P(t + ".norm1.bias")), None, P, t + ".attn1", cabecas)\\n    h = h + _atn(layer_norm(h, P(t + ".norm2.weight"), P(t + ".norm2.bias")), ctx, P, t + ".attn2", cabecas)\\n    f = layer_norm(h, P(t + ".norm3.weight"), P(t + ".norm3.bias"))\\n    f = linear(f, P(t + ".ff.net.0.proj.weight"), P(t + ".ff.net.0.proj.bias"))\\n    a, gate = np.split(f, 2, axis=-1)\\n    f = linear(a * gelu(gate), P(t + ".ff.net.2.weight"), P(t + ".ff.net.2.bias"))\\n    h = _proj(h + f, P, p + ".proj_out")\\n    return x + h.T.reshape(C, H, W)\\n\\n\\ndef embedding_tempo(t, dim, P, p):\\n    metade = dim // 2\\n    freq = np.exp(-np.log(10000.0) * np.arange(metade) / metade)\\n    a = t * freq\\n    e = np.concatenate([np.cos(a), np.sin(a)]).astype(np.float32)\\n    e = silu(linear(e, P(p + ".linear_1.weight"), P(p + ".linear_1.bias")))\\n    return linear(e, P(p + ".linear_2.weight"), P(p + ".linear_2.bias"))\\n\\n\\ndef mini_unet(x, t, ctx, P, canais=64, cabecas=4):\\n    """UNet pequeno (1 nivel) com os MESMOS blocos do SD, para provar o motor por partes."""\\n    temb = embedding_tempo(t, canais, P, "time_embedding")\\n    h = conv2d(x, P("conv_in.weight"), P("conv_in.bias"), pad=1)\\n    h = bloco_resnet(h, temb, P, "down.resnets.0", grupos=8)\\n    h = bloco_transformer(h, ctx, P, "down.attn.0", cabecas, grupos=8)\\n    pula = h\\n    h = conv2d(h, P("down.downsample.weight"), P("down.downsample.bias"), stride=2, pad=1)\\n    h = bloco_resnet(h, temb, P, "mid.resnets.0", grupos=8)\\n    h = sobe2x(h)\\n    h = conv2d(h, P("up.upsample.weight"), P("up.upsample.bias"), pad=1)\\n    h = bloco_resnet(np.concatenate([h, pula]), temb, P, "up.resnets.0", grupos=8)\\n    h = silu(group_norm(h, P("norm_out.weight"), P("norm_out.bias"), 8))\\n    return conv2d(h, P("conv_out.weight"), P("conv_out.bias"), pad=1)\\n\\n\\ndef pesos_aleatorios_mini(canais=64, ctx_dim=32, entrada=4, seed=0):\\n    r = np.random.default_rng(seed)\\n    n = lambda *s, e=0.05: (r.standard_normal(s) * e).astype(np.float32)\\n    uns = lambda c: np.ones(c, np.float32)\\n    z = lambda c: np.zeros(c, np.float32)\\n    C, T = canais, canais * 4\\n    s = {}\\n\\n    def res(p, cin, cout):\\n        s[p + ".norm1.weight"], s[p + ".norm1.bias"] = uns(cin), z(cin)\\n        s[p + ".conv1.weight"], s[p + ".conv1.bias"] = n(cout, cin, 3, 3), z(cout)\\n        s[p + ".time_emb_proj.weight"], s[p + ".time_emb_proj.bias"] = n(cout, T), z(cout)\\n        s[p + ".norm2.weight"], s[p + ".norm2.bias"] = uns(cout), z(cout)\\n        s[p + ".conv2.weight"], s[p + ".conv2.bias"] = n(cout, cout, 3, 3), z(cout)\\n        if cin != cout:\\n            s[p + ".conv_shortcut.weight"], s[p + ".conv_shortcut.bias"] = n(cout, cin, 1, 1), z(cout)\\n\\n    s["time_embedding.linear_1.weight"], s["time_embedding.linear_1.bias"] = n(T, C), z(T)\\n    s["time_embedding.linear_2.weight"], s["time_embedding.linear_2.bias"] = n(T, T), z(T)\\n    s["conv_in.weight"], s["conv_in.bias"] = n(C, entrada, 3, 3), z(C)\\n    res("down.resnets.0", C, C)\\n    p = "down.attn.0"\\n    s[p + ".norm.weight"], s[p + ".norm.bias"] = uns(C), z(C)\\n    s[p + ".proj_in.weight"], s[p + ".proj_in.bias"] = n(C, C, 1, 1), z(C)\\n    t = p + ".transformer_blocks.0"\\n    for k in (1, 2, 3):\\n        s["%s.norm%d.weight" % (t, k)], s["%s.norm%d.bias" % (t, k)] = uns(C), z(C)\\n    for a, dc in (("attn1", C), ("attn2", ctx_dim)):\\n        s["%s.%s.to_q.weight" % (t, a)] = n(C, C)\\n        s["%s.%s.to_k.weight" % (t, a)] = n(C, dc)\\n        s["%s.%s.to_v.weight" % (t, a)] = n(C, dc)\\n        s["%s.%s.to_out.0.weight" % (t, a)], s["%s.%s.to_out.0.bias" % (t, a)] = n(C, C), z(C)\\n    s[t + ".ff.net.0.proj.weight"], s[t + ".ff.net.0.proj.bias"] = n(C * 8, C), z(C * 8)\\n    s[t + ".ff.net.2.weight"], s[t + ".ff.net.2.bias"] = n(C, C * 4), z(C)\\n    s[p + ".proj_out.weight"], s[p + ".proj_out.bias"] = n(C, C, 1, 1), z(C)\\n    s["down.downsample.weight"], s["down.downsample.bias"] = n(C, C, 3, 3), z(C)\\n    res("mid.resnets.0", C, C)\\n    s["up.upsample.weight"], s["up.upsample.bias"] = n(C, C, 3, 3), z(C)\\n    res("up.resnets.0", 2 * C, C)\\n    s["norm_out.weight"], s["norm_out.bias"] = uns(C), z(C)\\n    s["conv_out.weight"], s["conv_out.bias"] = n(entrada, C, 3, 3), z(entrada)\\n    return s\\n\\n\\ndef medir_gflops(n=512, vezes=5):\\n    """Mede quantos GFLOPS ESTE aparelho faz com numpy (rode no celular e me mande o numero)."""\\n    a = np.random.rand(n, n).astype(np.float32)\\n    b = np.random.rand(n, n).astype(np.float32)\\n    a @ b\\n    t = time.time()\\n    for _ in range(vezes):\\n        a @ b\\n    seg = (time.time() - t) / vezes\\n    return 2.0 * n ** 3 / seg / 1e9\\n\\n\\ndef relatorio_aparelho():\\n    import os, platform\\n    g = medir_gflops()\\n    print("Python", platform.python_version(), "| numpy", np.__version__, "| nucleos", os.cpu_count())\\n    print("Velocidade de calculo: %.1f GFLOPS" % g)\\n    print("Tempo estimado = (GFLOP do modelo por passo) / %.1f  segundos" % g)\\n    return g\\n\\n\\nif __name__ == "__main__":\\n    relatorio_aparelho()\\n\'\n_U = \'"""UNet do segmind/tiny-sd em numpy puro, montado com os blocos do motor_cubico.\\n\\nArquitetura (lida de tinysd_config.json e do cabecalho do .ttq):\\n  conv_in 4->320 | down0 (320, resnet+atencao, reduz) | down1 (640, resnet+atencao, reduz)\\n  | down2 (1280, resnet+atencao) | SEM bloco do meio | up0 (1280, 2x[resnet+atencao], sobe)\\n  | up1 (640, 2x, sobe) | up2 (320, 2x) | norm -> silu -> conv_out 320->4\\n  8 cabecas de atencao, GEGLU exato (erf), tempo: seno/cosseno 320 -> 1280.\\n\\nCada bloco carrega seus pesos UMA vez e processa todas as amostras (condicional e\\nincondicional) antes de soltar; assim o pico de RAM e (ativacoes + pesos de UM bloco).\\nSTATUS: forma e fiacao testadas com pesos aleatorios; a igualdade com o torch so se prova\\nrodando validar_unet_tinysd contra tinysd_ref.npz (Colab).\\n"""\\nimport numpy as np\\n\\ntry:\\n    import motor_cubico as mc\\nexcept ImportError:\\n    from . import motor_cubico as mc\\n\\nCABECAS = 8\\n\\n\\ndef erf(x):\\n    """erf vetorizado (Abramowitz-Stegun 7.1.26, erro < 1.5e-7)."""\\n    s = np.sign(x)\\n    a = np.abs(x)\\n    t = 1.0 / (1.0 + 0.3275911 * a)\\n    y = 1.0 - (((((1.061405429 * t - 1.453152027) * t) + 1.421413741) * t - 0.284496736) * t\\n               + 0.254829592) * t * np.exp(-a * a)\\n    return (s * y).astype(np.float32)\\n\\n\\ndef gelu_exato(x):\\n    return (0.5 * x * (1.0 + erf(x * np.float32(0.70710678)))).astype(np.float32)\\n\\n\\nclass _Memo:\\n    """Carrega cada peso uma vez durante UM bloco (varias amostras reaproveitam)."""\\n\\n    def __init__(self, P):\\n        self.P, self.m = P, {}\\n\\n    def tem(self, nome):\\n        return self.P.tem(nome)\\n\\n    def __call__(self, nome):\\n        if nome not in self.m:\\n            self.m[nome] = self.P(nome)\\n        return self.m[nome]\\n\\n\\ndef transformer(x, ctx, P, p, cabecas=CABECAS):\\n    C, H, W = x.shape\\n    h = mc.group_norm(x, P(p + ".norm.weight"), P(p + ".norm.bias"), 32, eps=1e-6)\\n    h = mc._proj(h.reshape(C, H * W).T, P, p + ".proj_in")\\n    t = p + ".transformer_blocks.0"\\n    n1 = mc.layer_norm(h, P(t + ".norm1.weight"), P(t + ".norm1.bias"))\\n    h = h + mc._atn(n1, None, P, t + ".attn1", cabecas)\\n    n2 = mc.layer_norm(h, P(t + ".norm2.weight"), P(t + ".norm2.bias"))\\n    h = h + mc._atn(n2, ctx, P, t + ".attn2", cabecas)\\n    f = mc.layer_norm(h, P(t + ".norm3.weight"), P(t + ".norm3.bias"))\\n    f = mc.linear(f, P(t + ".ff.net.0.proj.weight"), P(t + ".ff.net.0.proj.bias"))\\n    a, gate = np.split(f, 2, axis=-1)\\n    f = mc.linear(a * gelu_exato(gate), P(t + ".ff.net.2.weight"), P(t + ".ff.net.2.bias"))\\n    h = mc._proj(h + f, P, p + ".proj_out")\\n    return (x + h.T.reshape(C, H, W)).astype(np.float32)\\n\\n\\ndef _res(xs, tembs, P, p):\\n    M = _Memo(P)\\n    return [mc.bloco_resnet(x, te, M, p) for x, te in zip(xs, tembs)]\\n\\n\\ndef _trf(xs, ctxs, P, p):\\n    M = _Memo(P)\\n    return [transformer(x, c, M, p) for x, c in zip(xs, ctxs)]\\n\\n\\ndef _conv(xs, P, nome, stride=1, pad=1):\\n    M = _Memo(P)\\n    w, b = M(nome + ".weight"), M(nome + ".bias")\\n    return [mc.conv2d(x, w, b, stride=stride, pad=pad) for x in xs]\\n\\n\\ndef unet_tinysd(xs, t, ctxs, P, captura=None):\\n    """xs: lista de latentes (4,H,W); ctxs: lista de (77,768), um por amostra; t: passo (numero).\\n    Devolve a lista de previsoes de ruido (4,H,W). `captura` (dict) recebe as ativacoes da\\n    amostra 0 com os mesmos nomes dos ganchos do script de exportacao."""\\n    cap = (lambda k, v: captura.__setitem__(k, np.array(v[0], np.float32))) if captura is not None \\\\\\n        else (lambda k, v: None)\\n    temb = mc.embedding_tempo(float(t), 320, P, "time_embedding")\\n    cap("time_embedding", [temb])\\n    tembs = [temb] * len(xs)\\n    hs = _conv(xs, P, "conv_in")\\n    cap("conv_in", hs)\\n    pilha = [hs]\\n    for i in range(3):                                      # descida\\n        b = "down_blocks.%d" % i\\n        hs = _res(hs, tembs, P, b + ".resnets.0")\\n        hs = _trf(hs, ctxs, P, b + ".attentions.0")\\n        pilha.append(hs)\\n        if i < 2:\\n            hs = _conv(hs, P, b + ".downsamplers.0.conv", stride=2)\\n            pilha.append(hs)\\n        cap("down_%d" % i, hs)\\n    for i in range(3):                                      # subida\\n        b = "up_blocks.%d" % i\\n        for j in range(2):\\n            pula = pilha.pop()\\n            hs = [np.concatenate([h, s]) for h, s in zip(hs, pula)]\\n            hs = _res(hs, tembs, P, b + ".resnets.%d" % j)\\n            hs = _trf(hs, ctxs, P, b + ".attentions.%d" % j)\\n        if i < 2:\\n            hs = [mc.sobe2x(h) for h in hs]\\n            hs = _conv(hs, P, b + ".upsamplers.0.conv")\\n        cap("up_%d" % i, hs)\\n    M = _Memo(P)\\n    g, bb = M("conv_norm_out.weight"), M("conv_norm_out.bias")\\n    hs = [mc.silu(mc.group_norm(h, g, bb, 32)) for h in hs]\\n    out = _conv(hs, P, "conv_out")\\n    cap("conv_out", out)\\n    return out\\n\'\ndef _mod(nome, codigo):\n    m = types.ModuleType(nome); sys.modules[nome] = m; exec(codigo, m.__dict__); return m\n_mod("cubo_quant", _C); mc = _mod("motor_cubico", _M); un = _mod("unet_tinysd", _U)\n\nref = np.load("tinysd_ref.npz")\nx = ref["latente"][0]; ctx = ref["texto_cond"][0]\ndef snr(a, b): return 10 * np.log10((a ** 2).mean() / (((a - b) ** 2).mean() + 1e-30))\narqs = [a for a in ("tinysd_unet_q8.ttq", "tinysd_unet_final.ttq", "tinysd_unet_curva.ttq") if os.path.exists(a)]\nprint("arquivos encontrados:", arqs or "NENHUM (rode antes colab_exportar_tinysd.py / evolucao / curva)")\nfor arq in arqs:\n    P = mc.Pesos(arq, cache_mb=0)                           # por partes: nada fica na RAM\n    print("\\n=== %s (%.0f MB) ===" % (arq, os.path.getsize(arq) / 1e6))\n    print("%-6s %-40s %10s" % ("t", "comparacao", "SNR (dB)"))\n    for t in (999, 500, 100):\n        cap = {}; t0 = time.time()\n        y = un.unet_tinysd([x], t, [ctx], P, cap)[0]; dt = time.time() - t0\n        if arq.endswith("q8.ttq"):\n            print("%-6d %-40s %10.1f" % (t, "numpy vs torch, MESMOS pesos (>60 = certo)", snr(ref["q8_t%d_saida" % t][0], y)))\n        print("%-6d %-40s %10.1f" % (t, "numpy vs torch original fp32", snr(ref["fp32_t%d_saida" % t][0], y)))\n        print("       passo (1 amostra) %.1f s | pico de RAM do processo %.0f MB" % (dt, resource.getrusage(resource.RUSAGE_SELF).ru_maxrss / 1024))\n        if t == 999 and arq.endswith("q8.ttq"):\n            print("       bloco a bloco (numpy vs torch q8):")\n            for k in ("conv_in", "time_embedding", "down_0", "down_1", "down_2", "up_0", "up_1", "up_2", "conv_out"):\n                r = ref["q8_t%d_%s" % (t, k)]; r = r[0] if r.ndim > 1 and r.shape[0] == 1 else r\n                print("         %-16s SNR %6.1f dB" % (k, snr(r, cap[k])))\n    print("leitura do .ttq: %d camadas, %.1f s lendo/desquantizando" % (P.leituras, P.t_leitura))\n', "validar CLIP+VAE": '# TTOKEN - VALIDA CLIP (texto) E VAE (decodificador) EM NUMPY CONTRA O TORCH. Rode no MESMO Colab das exportacoes.\n# Precisa de tinysd_ref.npz, tinysd_texto_q8.ttq e tinysd_vae_q8.ttq (gerados por colab_exportar_tinysd.py). Arquivo UNICO.\n# Os numeros de referencia vem do torch em fp32; os pesos aqui estao em 8 bits 4x4. Motor CORRETO = SNR alto (>= 30 dB);\n# um erro de fiacao derruba para < 15 dB.\nimport sys, types, time, os, resource\nimport numpy as np\n_C = \'"""CUBO-QUANT: quantizacao de pesos em CUBOS (blocos) de 4 bits + leitor em streaming.\\n\\nSem torch: so numpy. Serve para o Colab (comprimir) e para o Pydroid 3 (ler).\\n\\nO que era errado no codigo antigo (erro \\\'cannot reshape array of size 12800 into shape\\n(320,4,3,3)\\\'): para quantizar, a matriz era COMPLETADA com zeros ate ser multiplo de 8\\n(36 colunas -> 40; 320*40 = 12800), mas na hora de ler ninguem cortava esse enchimento antes de\\nvoltar a forma original (320*4*3*3 = 11520). Aqui a forma original e o tamanho real ficam\\ngravados no arquivo e o enchimento e sempre cortado.\\n\\nOutra correcao honesta: o "Q4" antigo guardava cada valor de 4 bits num int8 (1 byte), entao so\\nchegava a 1/4 do FP32. Aqui dois valores de 4 bits sao empacotados em 1 byte (1/8 do FP32).\\n\\nFormato .ttq:  b"TTQ1" | uint64 tamanho do cabecalho | cabecalho JSON | blobs (alinhados em 8).\\nCada tensor 2D+ vira matriz (linhas x resto); a matriz e cortada em cubos bh x bw; cada cubo tem\\nUMA escala (float16) = max|cubo| / 7; os valores vao de -8 a 7 (guardados como 0..15).\\n"""\\nimport json\\nimport mmap\\nimport os\\nimport struct\\nimport sys\\n\\nimport numpy as np\\n\\nMAGICO = b"TTQ1"\\nMIN_ELEMENTOS = 256          # tensores menores (bias, norm) ficam em float16, sem perda\\n\\n\\ndef _alinha(n, a=8):\\n    return (n + a - 1) // a * a\\n\\n\\ndef quantizar(arr, bloco=(8, 8), bits=4):\\n    """Devolve (empacotado uint8, escalas float16, linhas, colunas) de um tensor >= 2D.\\n    bits=4: 2 valores por byte (-8..7). bits=8: 1 valor por byte (-128..127), mais qualidade."""\\n    bh, bw = bloco\\n    arr = np.asarray(arr, dtype=np.float32)\\n    m = arr.reshape(arr.shape[0], -1)\\n    R, C = m.shape\\n    Rp, Cp = _alinha(R, bh), _alinha(C, bw)\\n    p = np.zeros((Rp, Cp), dtype=np.float32)\\n    p[:R, :C] = m\\n    b = p.reshape(Rp // bh, bh, Cp // bw, bw).transpose(0, 2, 1, 3)       # (nbh, nbw, bh, bw)\\n    maximo = np.abs(b).max(axis=(2, 3))\\n    nivel = 7.0 if bits == 4 else 127.0\\n    esc = np.where(maximo == 0, 1.0, maximo / nivel).astype(np.float16)\\n    esc32 = esc.astype(np.float32)                    # usa a escala JA arredondada (consistente)\\n    q = np.rint(b / esc32[:, :, None, None])\\n    if bits == 4:\\n        plano = (np.clip(q, -8, 7).astype(np.int8) + 8).astype(np.uint8).reshape(-1)\\n        if plano.size % 2:\\n            plano = np.concatenate([plano, np.zeros(1, np.uint8)])\\n        return ((plano[0::2] << 4) | plano[1::2]).astype(np.uint8), esc, R, C\\n    return (np.clip(q, -128, 127).astype(np.int16) + 128).astype(np.uint8).reshape(-1), esc, R, C\\n\\n\\ndef desquantizar(pack, esc, R, C, forma, bloco=(8, 8), dtype=np.float32, bits=4,\\n                 max_elementos=1 << 16):\\n    """Reconstroi POR PARTES (algumas linhas de cubos por vez): os temporarios ficam pequenos,\\n    so o resultado final ocupa a RAM do tensor. Corta o enchimento e volta a forma original."""\\n    bh, bw = bloco\\n    nbh, nbw = _alinha(R, bh) // bh, _alinha(C, bw) // bw\\n    esc = esc.astype(np.float32).reshape(nbh, nbw)\\n    por_linha = nbw * bh * bw                           # elementos de uma linha de cubos\\n    passo = max(1, max_elementos // por_linha)\\n    if bits == 4 and por_linha % 2:                     # cubo impar: nao da para partir no meio do byte\\n        passo = nbh\\n    out = np.empty((R, C), dtype=np.float32)\\n    for a in range(0, nbh, passo):\\n        z = min(nbh, a + passo)\\n        i0, i1 = a * por_linha, z * por_linha\\n        if bits == 4:\\n            bytes_ = pack[i0 // 2:(i1 + 1) // 2]\\n            plano = np.empty(bytes_.size * 2, dtype=np.uint8)\\n            plano[0::2] = bytes_ >> 4\\n            plano[1::2] = bytes_ & 15\\n            q = plano[:i1 - i0].astype(np.float32) - 8.0\\n        else:\\n            q = pack[i0:i1].astype(np.float32) - 128.0\\n        blocos = q.reshape(z - a, nbw, bh, bw) * esc[a:z, :, None, None]\\n        faixa = blocos.transpose(0, 2, 1, 3).reshape((z - a) * bh, nbw * bw)\\n        r0, r1 = a * bh, min(R, z * bh)\\n        out[r0:r1, :] = faixa[:r1 - r0, :C]\\n    return out.reshape(forma).astype(dtype, copy=False)\\n\\n\\ndef ordem_cubo(m):\\n    """Permutacao de linhas e colunas que junta valores de tamanho parecido (como arrumar as\\n    pecas do cubo magico por cor): ordena por energia. Cubos vizinhos ficam com faixa de valores\\n    parecida, a escala de cada cubo fica justa e o MESMO numero de bits erra menos."""\\n    pr = np.argsort(np.abs(m).max(axis=1))\\n    pc = np.argsort(np.abs(m).max(axis=0))\\n    return pr, pc\\n\\n\\ndef erro(original, recuperado):\\n    """Metricas honestas: SNR em dB, erro maximo e erro medio relativo."""\\n    o = np.asarray(original, np.float64).ravel()\\n    r = np.asarray(recuperado, np.float64).ravel()\\n    ruido = np.sum((o - r) ** 2)\\n    sinal = np.sum(o ** 2)\\n    snr = float("inf") if ruido == 0 else 10 * np.log10(max(sinal, 1e-30) / ruido)\\n    return {"snr_db": round(float(snr), 2), "erro_max": float(np.abs(o - r).max()),\\n            "erro_medio_rel": float(np.abs(o - r).mean() / (np.abs(o).mean() + 1e-12))}\\n\\n\\n# ------------------------------------------------------------------ gravar\\ndef salvar(estado, caminho, bloco=(8, 8), bits=4, reordenar=False, receita=None):\\n    """estado: dict nome -> ndarray. Grava o .ttq (atomico). Devolve estatisticas.\\n    receita (opcional): dict nome -> "fp16" | ((bh, bw), bits). Permite um cubo/precisao DIFERENTE por tensor\\n    (ex.: camadas sensiveis em fp16 ou 2x2, o resto em 4x4). Quem nao aparece usa (bloco, bits)."""\\n    receita = receita or {}\\n    meta, blobs, pos = {}, [], 0\\n    bruto = 0\\n    for nome, arr in estado.items():\\n        arr = np.asarray(arr)\\n        bruto += arr.size * 4\\n        rec = receita.get(nome)\\n        if rec == "fp16":\\n            rec_bloco, rec_bits = None, None\\n        else:\\n            rec_bloco, rec_bits = (tuple(rec[0]), int(rec[1])) if rec else (tuple(bloco), bits)\\n        if arr.ndim >= 2 and arr.size >= MIN_ELEMENTOS and rec != "fp16":\\n            m = arr.astype(np.float32).reshape(arr.shape[0], -1)\\n            pr = pc = None\\n            if reordenar:                                  # "resolve o cubo": agrupa parecidos\\n                pr, pc = ordem_cubo(m)\\n                m = m[pr][:, pc]\\n            pack, esc, R, C = quantizar(m, rec_bloco, rec_bits)\\n            dados = [pack.tobytes(), esc.tobytes()]\\n            meta[nome] = {"modo": "q%d" % rec_bits, "forma": list(arr.shape), "R": R, "C": C,\\n                          "off": pos, "n": len(dados[0]),\\n                          "off_esc": pos + _alinha(len(dados[0])), "n_esc": len(dados[1])}\\n            if rec:                                          # so grava por tensor quando a receita pediu\\n                meta[nome]["bloco"], meta[nome]["bits"] = list(rec_bloco), rec_bits\\n            tamanho = _alinha(len(dados[0])) + _alinha(len(dados[1]))\\n            blobs.append((pos, dados[0])); blobs.append((meta[nome]["off_esc"], dados[1]))\\n            if pr is not None:\\n                dr, dc = pr.astype(np.uint32).tobytes(), pc.astype(np.uint32).tobytes()\\n                meta[nome]["off_pr"], meta[nome]["off_pc"] = pos + tamanho, pos + tamanho + _alinha(len(dr))\\n                blobs.append((meta[nome]["off_pr"], dr)); blobs.append((meta[nome]["off_pc"], dc))\\n                tamanho += _alinha(len(dr)) + _alinha(len(dc))\\n        else:\\n            d = np.ascontiguousarray(arr.astype(np.float16)).tobytes()\\n            meta[nome] = {"modo": "f16", "forma": list(arr.shape), "off": pos, "n": len(d)}\\n            blobs.append((pos, d))\\n            tamanho = _alinha(len(d))\\n        pos += tamanho\\n    cab = json.dumps({"bloco": list(bloco), "bits": bits, "tensores": meta}).encode("utf-8")\\n    ini = _alinha(4 + 8 + len(cab))\\n    tmp = caminho + ".tmp"\\n    with open(tmp, "wb") as f:\\n        f.write(MAGICO + struct.pack("<Q", len(cab)) + cab)\\n        f.write(b"\\\\0" * (ini - 12 - len(cab)))\\n        for off, d in blobs:\\n            f.seek(ini + off)\\n            f.write(d)\\n        f.truncate(ini + pos)\\n    os.replace(tmp, caminho)\\n    final = os.path.getsize(caminho)\\n    return {"bruto_fp32_mb": bruto / 2**20, "arquivo_mb": final / 2**20,\\n            "economia_pct": round(100 * (1 - final / max(bruto, 1)), 1)}\\n\\n\\n# ------------------------------------------------------------------ ler (streaming)\\nclass Leitor:\\n    """Le UM tensor por vez direto do arquivo (mmap): a RAM so guarda o tensor em uso."""\\n\\n    def __init__(self, caminho):\\n        self._f = open(caminho, "rb")\\n        if self._f.read(4) != MAGICO:\\n            self._f.close()\\n            raise ValueError("arquivo nao e um .ttq valido")\\n        (n,) = struct.unpack("<Q", self._f.read(8))\\n        cab = json.loads(self._f.read(n).decode("utf-8"))\\n        self.bloco = tuple(cab["bloco"])\\n        self.bits = int(cab.get("bits", 4))\\n        self.meta = cab["tensores"]\\n        self._ini = _alinha(12 + n)\\n        self._mm = mmap.mmap(self._f.fileno(), 0, access=mmap.ACCESS_READ)\\n\\n    def nomes(self):\\n        return list(self.meta)\\n\\n    def ler(self, nome, dtype=np.float32):\\n        t = self.meta[nome]\\n        forma = tuple(t["forma"])\\n        base = self._ini\\n        if t["modo"] == "f16":\\n            d = np.frombuffer(self._mm, np.float16, count=int(np.prod(forma, dtype=np.int64)),\\n                              offset=base + t["off"])\\n            return d.reshape(forma).astype(dtype)\\n        pack = np.frombuffer(self._mm, np.uint8, count=t["n"], offset=base + t["off"])\\n        esc = np.frombuffer(self._mm, np.float16, count=t["n_esc"] // 2,\\n                            offset=base + t["off_esc"])\\n        bloco_t = tuple(t.get("bloco", self.bloco))\\n        bits_t = int(t.get("bits", self.bits))\\n        bh, bw = bloco_t\\n        esc = esc.reshape(_alinha(t["R"], bh) // bh, _alinha(t["C"], bw) // bw)\\n        if "off_pr" in t:                                    # desfaz a reordenacao do cubo\\n            m = desquantizar(pack, esc, t["R"], t["C"], (t["R"], t["C"]), bloco_t, np.float32, bits_t)\\n            pr = np.frombuffer(self._mm, np.uint32, count=t["R"], offset=base + t["off_pr"])\\n            pc = np.frombuffer(self._mm, np.uint32, count=t["C"], offset=base + t["off_pc"])\\n            ir, ic = np.argsort(pr), np.argsort(pc)\\n            return m[ir][:, ic].reshape(forma).astype(dtype, copy=False)\\n        return desquantizar(pack, esc, t["R"], t["C"], forma, bloco_t, dtype, bits_t)\\n\\n    def ler_filas(self, nome, filas, dtype=np.float32):\\n        """Le SO as linhas pedidas (ex.: 77 tokens de um embedding de 49408 linhas), sem desquantizar o tensor todo."""\\n        filas = np.asarray(filas, np.int64).reshape(-1)\\n        t = self.meta[nome]\\n        forma = tuple(t["forma"])\\n        base = self._ini\\n        if t["modo"] == "f16":\\n            d = np.frombuffer(self._mm, np.float16, count=int(np.prod(forma, dtype=np.int64)), offset=base + t["off"])\\n            return d.reshape(forma[0], -1)[filas].astype(dtype)\\n        bloco_t, bits_t = tuple(t.get("bloco", self.bloco)), int(t.get("bits", self.bits))\\n        bh, bw = bloco_t\\n        R, C = t["R"], t["C"]\\n        nbw = _alinha(C, bw) // bw\\n        por = nbw * bh * bw\\n        if "off_pr" in t or (bits_t == 4 and por % 2):       # casos raros: le tudo\\n            return self.ler(nome, dtype).reshape(R, -1)[filas]\\n        pack = np.frombuffer(self._mm, np.uint8, count=t["n"], offset=base + t["off"])\\n        esc = np.frombuffer(self._mm, np.float16, count=t["n_esc"] // 2, offset=base + t["off_esc"])\\n        esc = esc.reshape(_alinha(R, bh) // bh, nbw)\\n        bandas = {}\\n        for a in np.unique(filas // bh):\\n            ps = pack[a * por: (a + 1) * por] if bits_t == 8 else pack[a * por // 2: (a + 1) * por // 2]\\n            bandas[int(a)] = desquantizar(ps, esc[a:a + 1], bh, C, (bh, C), bloco_t, np.float32, bits_t)\\n        return np.stack([bandas[int(f // bh)][int(f % bh)] for f in filas]).astype(dtype, copy=False)\\n\\n    def itens(self):\\n        for nome in self.meta:\\n            yield nome, self.ler(nome)\\n\\n    def fechar(self):\\n        try:\\n            self._mm.close()\\n        finally:\\n            self._f.close()\\n\\n    def __enter__(self):\\n        return self\\n\\n    def __exit__(self, *a):\\n        self.fechar()\\n\\n\\ndef para_torch(caminho, dispositivo="cpu", dtype_nome="float16"):\\n    """Colab: monta um state_dict do PyTorch lendo o .ttq (importa torch so aqui)."""\\n    import torch\\n    dt = getattr(torch, dtype_nome)\\n    sd = {}\\n    with Leitor(caminho) as lt:\\n        for nome, arr in lt.itens():\\n            sd[nome] = torch.from_numpy(arr).to(dispositivo).to(dt)\\n    return sd\\n\\n\\ndef de_safetensors(entrada, saida, bloco=(8, 8), bits=4):\\n    """Converte um .safetensors (so float32/float16) em .ttq. Precisa de `safetensors`."""\\n    from safetensors.numpy import load_file\\n    return salvar(load_file(entrada), saida, bloco, bits)\\n\\n\\nif __name__ == "__main__":      # python cubo_quant.py modelo.safetensors saida.ttq\\n    if len(sys.argv) != 3:\\n        print("uso: python cubo_quant.py entrada.safetensors saida.ttq")\\n        sys.exit(1)\\n    print(de_safetensors(sys.argv[1], sys.argv[2]))\\n\'\n_M = \'"""MOTOR CUBICO: roda camadas de uma rede de difusao em numpy (Python puro, sem torch),\\nlendo os pesos de um arquivo .ttq (cubos de 4 bits) UMA CAMADA POR VEZ.\\n\\nIdeia (do Fabio): o modelo e maior que a RAM do celular, entao\\n  1) os pesos ficam comprimidos em cubos de 4 bits no armazenamento (cubo_quant.py);\\n  2) a cada camada o motor "abre" so aquele pedaco, calcula e joga fora;\\n  3) as contas grandes (convolucao, atencao) tambem andam por partes (linhas / blocos).\\nO pico de RAM fica perto de  (ativacoes + a MAIOR camada)  e nao do tamanho do modelo.\\n\\nNomes dos pesos seguem o diffusers (resnets.0.norm1, attn1.to_q, ff.net.0.proj ...), entao\\nportar o UNet real do SDXS/SD e compor estes blocos. Os blocos sao validados contra\\nimplementacoes ingenuas nos testes; o UNet COMPLETO real ainda NAO foi validado (precisa dos\\npesos reais e de uma referencia).\\n"""\\nimport time\\nfrom collections import OrderedDict\\n\\nimport numpy as np\\nfrom numpy.lib.stride_tricks import sliding_window_view\\n\\ntry:\\n    import cubo_quant as cq\\nexcept ImportError:                                  # quando importado como pacote\\n    from . import cubo_quant as cq\\n\\n\\n# ------------------------------------------------------------------ pesos por partes\\nclass Pesos:\\n    """Entrega pesos float32 de um .ttq. cache_mb=0: nada fica na RAM depois do uso."""\\n\\n    def __init__(self, caminho, cache_mb=0):\\n        self.lt = cq.Leitor(caminho)\\n        self.cache_mb, self._cache, self._bytes = cache_mb, OrderedDict(), 0\\n        self.leituras = 0\\n        self.t_leitura = 0.0\\n\\n    def tem(self, nome):\\n        return nome in self.lt.meta\\n\\n    def __call__(self, nome):\\n        if nome in self._cache:\\n            self._cache.move_to_end(nome)\\n            return self._cache[nome]\\n        t = time.time()\\n        a = self.lt.ler(nome)\\n        self.t_leitura += time.time() - t\\n        self.leituras += 1\\n        if self.cache_mb and a.nbytes <= self.cache_mb * 2**20:\\n            self._cache[nome] = a\\n            self._bytes += a.nbytes\\n            while self._bytes > self.cache_mb * 2**20:\\n                _, v = self._cache.popitem(last=False)\\n                self._bytes -= v.nbytes\\n        return a\\n\\n    def fechar(self):\\n        self.lt.fechar()\\n\\n\\nclass PesosMemoria:\\n    """Mesma interface, pesos ja em RAM (referencia para comparar)."""\\n\\n    def __init__(self, estado):\\n        self.e = {k: np.asarray(v, np.float32) for k, v in estado.items()}\\n\\n    def tem(self, nome):\\n        return nome in self.e\\n\\n    def __call__(self, nome):\\n        return self.e[nome]\\n\\n\\n# ------------------------------------------------------------------ operacoes\\ndef silu(x):\\n    return x / (1.0 + np.exp(-x))\\n\\n\\ndef gelu(x):                                         # aproximacao tanh (erro ~1e-3)\\n    return 0.5 * x * (1.0 + np.tanh(0.7978845608 * (x + 0.044715 * x ** 3)))\\n\\n\\ndef linear(x, w, b=None):\\n    y = x @ w.T\\n    return y + b if b is not None else y\\n\\n\\ndef conv2d(x, w, b=None, stride=1, pad=0, linhas=16):\\n    """x (C,H,W), w (O,C,kh,kw). Anda `linhas` linhas de saida por vez (pouca RAM)."""\\n    C, H, W = x.shape\\n    O, _, kh, kw = w.shape\\n    xp = np.pad(x, ((0, 0), (pad, pad), (pad, pad))) if pad else x\\n    Ho, Wo = (H + 2 * pad - kh) // stride + 1, (W + 2 * pad - kw) // stride + 1\\n    out = np.empty((O, Ho, Wo), np.float32)\\n    wm = w.reshape(O, -1)\\n    jan = sliding_window_view(xp, (kh, kw), axis=(1, 2))[:, ::stride, ::stride]\\n    for r0 in range(0, Ho, linhas):\\n        r1 = min(Ho, r0 + linhas)\\n        cols = jan[:, r0:r1].transpose(1, 2, 0, 3, 4).reshape((r1 - r0) * Wo, C * kh * kw)\\n        out[:, r0:r1, :] = (cols @ wm.T).reshape(r1 - r0, Wo, O).transpose(2, 0, 1)\\n    if b is not None:\\n        out += b[:, None, None]\\n    return out\\n\\n\\ndef group_norm(x, g, b, grupos=32, eps=1e-5):\\n    C, H, W = x.shape\\n    xg = x.reshape(grupos, -1)\\n    m = xg.mean(axis=1, keepdims=True)\\n    v = xg.var(axis=1, keepdims=True)\\n    y = ((xg - m) / np.sqrt(v + eps)).reshape(C, H, W)\\n    return y * g[:, None, None] + b[:, None, None]\\n\\n\\ndef layer_norm(x, g, b, eps=1e-5):\\n    m = x.mean(-1, keepdims=True)\\n    v = x.var(-1, keepdims=True)\\n    return (x - m) / np.sqrt(v + eps) * g + b\\n\\n\\ndef atencao(q, k, v, cabecas, bloco=256):\\n    """q (N,D), k/v (M,D). Softmax por blocos de consultas (nao monta a matriz NxM inteira)."""\\n    N, D = q.shape\\n    d = D // cabecas\\n    qh = q.reshape(N, cabecas, d).transpose(1, 0, 2)\\n    kh = k.reshape(-1, cabecas, d).transpose(1, 2, 0)\\n    vh = v.reshape(-1, cabecas, d).transpose(1, 0, 2)\\n    out = np.empty((cabecas, N, d), np.float32)\\n    esc = 1.0 / np.sqrt(d)\\n    for i in range(0, N, bloco):\\n        s = (qh[:, i:i + bloco] @ kh) * esc\\n        s -= s.max(-1, keepdims=True)\\n        p = np.exp(s)\\n        p /= p.sum(-1, keepdims=True)\\n        out[:, i:i + bloco] = p @ vh\\n    return out.transpose(1, 0, 2).reshape(N, D)\\n\\n\\ndef sobe2x(x):\\n    return x.repeat(2, axis=1).repeat(2, axis=2)\\n\\n\\ndef _b(P, nome):\\n    return P(nome) if P.tem(nome) else None\\n\\n\\n# ------------------------------------------------------------------ blocos (nomes do diffusers)\\ndef bloco_resnet(x, temb, P, p, grupos=32):\\n    h = silu(group_norm(x, P(p + ".norm1.weight"), P(p + ".norm1.bias"), grupos))\\n    h = conv2d(h, P(p + ".conv1.weight"), P(p + ".conv1.bias"), pad=1)\\n    if temb is not None and P.tem(p + ".time_emb_proj.weight"):\\n        t = linear(silu(temb), P(p + ".time_emb_proj.weight"), P(p + ".time_emb_proj.bias"))\\n        h = h + t[:, None, None]\\n    h = silu(group_norm(h, P(p + ".norm2.weight"), P(p + ".norm2.bias"), grupos))\\n    h = conv2d(h, P(p + ".conv2.weight"), P(p + ".conv2.bias"), pad=1)\\n    if P.tem(p + ".conv_shortcut.weight"):\\n        x = conv2d(x, P(p + ".conv_shortcut.weight"), P(p + ".conv_shortcut.bias"))\\n    return x + h\\n\\n\\ndef _proj(h, P, nome):                               # conv 1x1 ou linear, conforme o peso\\n    w = P(nome + ".weight")\\n    b = _b(P, nome + ".bias")\\n    return linear(h, w.reshape(w.shape[0], -1), b)\\n\\n\\ndef _atn(h, ctx, P, p, cabecas):\\n    ctx = h if ctx is None else ctx\\n    q = linear(h, P(p + ".to_q.weight"))\\n    k = linear(ctx, P(p + ".to_k.weight"))\\n    v = linear(ctx, P(p + ".to_v.weight"))\\n    o = atencao(q, k, v, cabecas)\\n    return linear(o, P(p + ".to_out.0.weight"), P(p + ".to_out.0.bias"))\\n\\n\\ndef bloco_transformer(x, ctx, P, p, cabecas=8, grupos=32):\\n    C, H, W = x.shape\\n    h = group_norm(x, P(p + ".norm.weight"), P(p + ".norm.bias"), grupos, eps=1e-6)\\n    h = h.reshape(C, H * W).T\\n    h = _proj(h, P, p + ".proj_in")\\n    t = p + ".transformer_blocks.0"\\n    h = h + _atn(layer_norm(h, P(t + ".norm1.weight"), P(t + ".norm1.bias")), None, P, t + ".attn1", cabecas)\\n    h = h + _atn(layer_norm(h, P(t + ".norm2.weight"), P(t + ".norm2.bias")), ctx, P, t + ".attn2", cabecas)\\n    f = layer_norm(h, P(t + ".norm3.weight"), P(t + ".norm3.bias"))\\n    f = linear(f, P(t + ".ff.net.0.proj.weight"), P(t + ".ff.net.0.proj.bias"))\\n    a, gate = np.split(f, 2, axis=-1)\\n    f = linear(a * gelu(gate), P(t + ".ff.net.2.weight"), P(t + ".ff.net.2.bias"))\\n    h = _proj(h + f, P, p + ".proj_out")\\n    return x + h.T.reshape(C, H, W)\\n\\n\\ndef embedding_tempo(t, dim, P, p):\\n    metade = dim // 2\\n    freq = np.exp(-np.log(10000.0) * np.arange(metade) / metade)\\n    a = t * freq\\n    e = np.concatenate([np.cos(a), np.sin(a)]).astype(np.float32)\\n    e = silu(linear(e, P(p + ".linear_1.weight"), P(p + ".linear_1.bias")))\\n    return linear(e, P(p + ".linear_2.weight"), P(p + ".linear_2.bias"))\\n\\n\\ndef mini_unet(x, t, ctx, P, canais=64, cabecas=4):\\n    """UNet pequeno (1 nivel) com os MESMOS blocos do SD, para provar o motor por partes."""\\n    temb = embedding_tempo(t, canais, P, "time_embedding")\\n    h = conv2d(x, P("conv_in.weight"), P("conv_in.bias"), pad=1)\\n    h = bloco_resnet(h, temb, P, "down.resnets.0", grupos=8)\\n    h = bloco_transformer(h, ctx, P, "down.attn.0", cabecas, grupos=8)\\n    pula = h\\n    h = conv2d(h, P("down.downsample.weight"), P("down.downsample.bias"), stride=2, pad=1)\\n    h = bloco_resnet(h, temb, P, "mid.resnets.0", grupos=8)\\n    h = sobe2x(h)\\n    h = conv2d(h, P("up.upsample.weight"), P("up.upsample.bias"), pad=1)\\n    h = bloco_resnet(np.concatenate([h, pula]), temb, P, "up.resnets.0", grupos=8)\\n    h = silu(group_norm(h, P("norm_out.weight"), P("norm_out.bias"), 8))\\n    return conv2d(h, P("conv_out.weight"), P("conv_out.bias"), pad=1)\\n\\n\\ndef pesos_aleatorios_mini(canais=64, ctx_dim=32, entrada=4, seed=0):\\n    r = np.random.default_rng(seed)\\n    n = lambda *s, e=0.05: (r.standard_normal(s) * e).astype(np.float32)\\n    uns = lambda c: np.ones(c, np.float32)\\n    z = lambda c: np.zeros(c, np.float32)\\n    C, T = canais, canais * 4\\n    s = {}\\n\\n    def res(p, cin, cout):\\n        s[p + ".norm1.weight"], s[p + ".norm1.bias"] = uns(cin), z(cin)\\n        s[p + ".conv1.weight"], s[p + ".conv1.bias"] = n(cout, cin, 3, 3), z(cout)\\n        s[p + ".time_emb_proj.weight"], s[p + ".time_emb_proj.bias"] = n(cout, T), z(cout)\\n        s[p + ".norm2.weight"], s[p + ".norm2.bias"] = uns(cout), z(cout)\\n        s[p + ".conv2.weight"], s[p + ".conv2.bias"] = n(cout, cout, 3, 3), z(cout)\\n        if cin != cout:\\n            s[p + ".conv_shortcut.weight"], s[p + ".conv_shortcut.bias"] = n(cout, cin, 1, 1), z(cout)\\n\\n    s["time_embedding.linear_1.weight"], s["time_embedding.linear_1.bias"] = n(T, C), z(T)\\n    s["time_embedding.linear_2.weight"], s["time_embedding.linear_2.bias"] = n(T, T), z(T)\\n    s["conv_in.weight"], s["conv_in.bias"] = n(C, entrada, 3, 3), z(C)\\n    res("down.resnets.0", C, C)\\n    p = "down.attn.0"\\n    s[p + ".norm.weight"], s[p + ".norm.bias"] = uns(C), z(C)\\n    s[p + ".proj_in.weight"], s[p + ".proj_in.bias"] = n(C, C, 1, 1), z(C)\\n    t = p + ".transformer_blocks.0"\\n    for k in (1, 2, 3):\\n        s["%s.norm%d.weight" % (t, k)], s["%s.norm%d.bias" % (t, k)] = uns(C), z(C)\\n    for a, dc in (("attn1", C), ("attn2", ctx_dim)):\\n        s["%s.%s.to_q.weight" % (t, a)] = n(C, C)\\n        s["%s.%s.to_k.weight" % (t, a)] = n(C, dc)\\n        s["%s.%s.to_v.weight" % (t, a)] = n(C, dc)\\n        s["%s.%s.to_out.0.weight" % (t, a)], s["%s.%s.to_out.0.bias" % (t, a)] = n(C, C), z(C)\\n    s[t + ".ff.net.0.proj.weight"], s[t + ".ff.net.0.proj.bias"] = n(C * 8, C), z(C * 8)\\n    s[t + ".ff.net.2.weight"], s[t + ".ff.net.2.bias"] = n(C, C * 4), z(C)\\n    s[p + ".proj_out.weight"], s[p + ".proj_out.bias"] = n(C, C, 1, 1), z(C)\\n    s["down.downsample.weight"], s["down.downsample.bias"] = n(C, C, 3, 3), z(C)\\n    res("mid.resnets.0", C, C)\\n    s["up.upsample.weight"], s["up.upsample.bias"] = n(C, C, 3, 3), z(C)\\n    res("up.resnets.0", 2 * C, C)\\n    s["norm_out.weight"], s["norm_out.bias"] = uns(C), z(C)\\n    s["conv_out.weight"], s["conv_out.bias"] = n(entrada, C, 3, 3), z(entrada)\\n    return s\\n\\n\\ndef medir_gflops(n=512, vezes=5):\\n    """Mede quantos GFLOPS ESTE aparelho faz com numpy (rode no celular e me mande o numero)."""\\n    a = np.random.rand(n, n).astype(np.float32)\\n    b = np.random.rand(n, n).astype(np.float32)\\n    a @ b\\n    t = time.time()\\n    for _ in range(vezes):\\n        a @ b\\n    seg = (time.time() - t) / vezes\\n    return 2.0 * n ** 3 / seg / 1e9\\n\\n\\ndef relatorio_aparelho():\\n    import os, platform\\n    g = medir_gflops()\\n    print("Python", platform.python_version(), "| numpy", np.__version__, "| nucleos", os.cpu_count())\\n    print("Velocidade de calculo: %.1f GFLOPS" % g)\\n    print("Tempo estimado = (GFLOP do modelo por passo) / %.1f  segundos" % g)\\n    return g\\n\\n\\nif __name__ == "__main__":\\n    relatorio_aparelho()\\n\'\n_V = \'"""CLIP (texto) e VAE (decodificador) do tiny-sd em numpy puro, lendo os pesos do .ttq por partes.\\n\\nclip_texto(ids, P)       ids (77,) inteiros -> (77, 768)   [= text_encoder(ids).last_hidden_state]\\nvae_decodificar(z, P)    z (4,H,W) JA dividido por scaling_factor (0.18215) -> (3, 8H, 8W) em [-1, 1]\\n\\nSTATUS: forma e fiacao testadas com pesos aleatorios; a igualdade com o torch so se prova rodando\\ncolab_validar_clip_vae.py contra tinysd_ref.npz (Colab).\\n"""\\nimport numpy as np\\n\\ntry:\\n    import motor_cubico as mc\\nexcept ImportError:\\n    from . import motor_cubico as mc\\n\\n\\ndef _sig(x):\\n    return 1.0 / (1.0 + np.exp(-x))\\n\\n\\ndef _linhas(P, nome, idx):\\n    lt = getattr(P, "lt", None)\\n    if lt is not None and hasattr(lt, "ler_filas"):\\n        return lt.ler_filas(nome, idx)\\n    return np.asarray(P(nome))[idx]\\n\\n\\n# ------------------------------------------------------------------ CLIP\\ndef _atencao_causal(h, P, p, cabecas):\\n    N, D = h.shape\\n    d = D // cabecas\\n    q = mc.linear(h, P(p + ".q_proj.weight"), P(p + ".q_proj.bias")) * (d ** -0.5)\\n    k = mc.linear(h, P(p + ".k_proj.weight"), P(p + ".k_proj.bias"))\\n    v = mc.linear(h, P(p + ".v_proj.weight"), P(p + ".v_proj.bias"))\\n    qh, kh, vh = [a.reshape(N, cabecas, d).transpose(1, 0, 2) for a in (q, k, v)]\\n    s = qh @ kh.transpose(0, 2, 1)\\n    s = s + np.triu(np.full((N, N), -np.inf, np.float32), 1)       # cada token so ve os anteriores\\n    s -= s.max(-1, keepdims=True)\\n    e = np.exp(s)\\n    e /= e.sum(-1, keepdims=True)\\n    o = (e @ vh).transpose(1, 0, 2).reshape(N, D)\\n    return mc.linear(o, P(p + ".out_proj.weight"), P(p + ".out_proj.bias"))\\n\\n\\ndef clip_texto(ids, P, camadas=12, cabecas=12):\\n    ids = np.asarray(ids, np.int64).reshape(-1)\\n    N = len(ids)\\n    h = _linhas(P, "embeddings.token_embedding.weight", ids) + np.asarray(P("embeddings.position_embedding.weight"))[:N]\\n    h = h.astype(np.float32)\\n    for i in range(camadas):\\n        p = "encoder.layers.%d" % i\\n        a = mc.layer_norm(h, P(p + ".layer_norm1.weight"), P(p + ".layer_norm1.bias"))\\n        h = h + _atencao_causal(a, P, p + ".self_attn", cabecas)\\n        m = mc.layer_norm(h, P(p + ".layer_norm2.weight"), P(p + ".layer_norm2.bias"))\\n        m = mc.linear(m, P(p + ".mlp.fc1.weight"), P(p + ".mlp.fc1.bias"))\\n        m = m * _sig(1.702 * m)                                     # quick_gelu\\n        h = h + mc.linear(m, P(p + ".mlp.fc2.weight"), P(p + ".mlp.fc2.bias"))\\n    return mc.layer_norm(h, P("final_layer_norm.weight"), P("final_layer_norm.bias")).astype(np.float32)\\n\\n\\n# ------------------------------------------------------------------ VAE\\nEPS_VAE = 1e-6\\n\\n\\ndef _resnet_vae(x, P, p):\\n    h = mc.silu(mc.group_norm(x, P(p + ".norm1.weight"), P(p + ".norm1.bias"), 32, EPS_VAE))\\n    h = mc.conv2d(h, P(p + ".conv1.weight"), P(p + ".conv1.bias"), pad=1)\\n    h = mc.silu(mc.group_norm(h, P(p + ".norm2.weight"), P(p + ".norm2.bias"), 32, EPS_VAE))\\n    h = mc.conv2d(h, P(p + ".conv2.weight"), P(p + ".conv2.bias"), pad=1)\\n    if P.tem(p + ".conv_shortcut.weight"):\\n        x = mc.conv2d(x, P(p + ".conv_shortcut.weight"), P(p + ".conv_shortcut.bias"))\\n    return x + h\\n\\n\\ndef _atencao_vae(x, P, p):\\n    C, H, W = x.shape\\n    h = mc.group_norm(x, P(p + ".group_norm.weight"), P(p + ".group_norm.bias"), 32, EPS_VAE)\\n    h = h.reshape(C, H * W).T\\n    q = mc.linear(h, P(p + ".to_q.weight"), P(p + ".to_q.bias"))\\n    k = mc.linear(h, P(p + ".to_k.weight"), P(p + ".to_k.bias"))\\n    v = mc.linear(h, P(p + ".to_v.weight"), P(p + ".to_v.bias"))\\n    o = mc.atencao(q, k, v, 1)                                       # uma cabeca de dimensao C\\n    o = mc.linear(o, P(p + ".to_out.0.weight"), P(p + ".to_out.0.bias"))\\n    return x + o.T.reshape(C, H, W)\\n\\n\\ndef vae_decodificar(z, P):\\n    z = np.asarray(z, np.float32)\\n    h = mc.conv2d(z, P("post_quant_conv.weight"), P("post_quant_conv.bias"))\\n    h = mc.conv2d(h, P("decoder.conv_in.weight"), P("decoder.conv_in.bias"), pad=1)\\n    h = _resnet_vae(h, P, "decoder.mid_block.resnets.0")\\n    h = _atencao_vae(h, P, "decoder.mid_block.attentions.0")\\n    h = _resnet_vae(h, P, "decoder.mid_block.resnets.1")\\n    for i in range(4):\\n        b = "decoder.up_blocks.%d" % i\\n        for j in range(3):\\n            h = _resnet_vae(h, P, "%s.resnets.%d" % (b, j))\\n        if P.tem(b + ".upsamplers.0.conv.weight"):\\n            h = mc.sobe2x(h)\\n            h = mc.conv2d(h, P(b + ".upsamplers.0.conv.weight"), P(b + ".upsamplers.0.conv.bias"), pad=1)\\n    h = mc.silu(mc.group_norm(h, P("decoder.conv_norm_out.weight"), P("decoder.conv_norm_out.bias"), 32, EPS_VAE))\\n    return mc.conv2d(h, P("decoder.conv_out.weight"), P("decoder.conv_out.bias"), pad=1)\\n\\n\\ndef para_imagem(x):\\n    """(3,H,W) em [-1,1] -> uint8 (H,W,3)."""\\n    return np.clip((x.transpose(1, 2, 0) * 0.5 + 0.5) * 255.0 + 0.5, 0, 255).astype(np.uint8)\\n\'\ndef _mod(nome, codigo):\n    m = types.ModuleType(nome); sys.modules[nome] = m; exec(codigo, m.__dict__); return m\n_mod("cubo_quant", _C); mc = _mod("motor_cubico", _M); cv = _mod("clip_vae_tinysd", _V)\n\nref = np.load("tinysd_ref.npz")\ndef snr(a, b): return 10 * np.log10((a ** 2).mean() / (((a - b) ** 2).mean() + 1e-30))\nram = lambda: resource.getrusage(resource.RUSAGE_SELF).ru_maxrss / 1024\n\nprint("=== CLIP (texto) ===")\nP = mc.Pesos("tinysd_texto_q8.ttq", cache_mb=0)\nfor rot in ("cond", "incond"):\n    t0 = time.time(); y = cv.clip_texto(ref["ids_" + rot][0], P); dt = time.time() - t0\n    r = ref["texto_" + rot][0]\n    print("  %-7s SNR vs torch fp32: %6.1f dB | %.1f s | pico RAM do processo %.0f MB" % (rot, snr(r, y), dt, ram()))\nP.fechar()\n\nprint("\\n=== VAE (decodificador) ===")\nP = mc.Pesos("tinysd_vae_q8.ttq", cache_mb=0)\nt0 = time.time(); y = cv.vae_decodificar(ref["vae_entrada"][0], P); dt = time.time() - t0\nr = ref["vae_saida"][0]\nprint("  imagem %s SNR vs torch fp32: %.1f dB | %.1f s | pico RAM do processo %.0f MB" % (tuple(y.shape), snr(r, y), dt, ram()))\npsnr_pix = 10 * np.log10(255 ** 2 / np.mean((cv.para_imagem(r).astype(np.float64) - cv.para_imagem(y)) ** 2 + 1e-12))\nprint("  PSNR em pixels (0-255): %.1f dB   (>= 35 = imagens iguais a olho)" % psnr_pix)\ntry:\n    from PIL import Image\n    Image.fromarray(cv.para_imagem(y).transpose(1, 0, 2).transpose(1, 0, 2)).save("tinysd_vae_numpy.png")\n    print("  salvo tinysd_vae_numpy.png")\nexcept Exception as e:\n    print("  (sem PIL: %s)" % e)\nP.fechar()\nprint("\\nSe CLIP e VAE passarem de ~30 dB, os dois estao corretos e falta so o agendador + o tokenizador.")\n'}
